# Starts the writer, which reads reply file names from the FIFO and copies
# each file to stdout whole. A name is short, so writing one to the FIFO is
# atomic. Without a FIFO, replies go straight to stdout.
start_writer() {
  base="$ROOT/run~"
  mkdir -p "$base" 2>/dev/null || return 0
  n=0
  until mkdir "$base/$$.$n" 2>/dev/null; do
    n=$((n + 1))
    [ "$n" -lt 100 ] || return 0
  done
  r="$base/$$.$n"
  if ! mkfifo "$r/out" 2>/dev/null; then
    rm -rf "$r"
    return 0
  fi
  (
    while IFS= read -r f; do
      cat "$r/$f"
      rm -f "$r/$f"
    done
  ) <"$r/out" &
  WRITER=$!
  exec 3>"$r/out"
  RUN=$r
}

# Forgets the waiters that have finished.
prune() {
  keep=""
  for j in $JOBS; do
    if [ -f "$DIR/${j#*:}/waiting" ]; then keep="$keep $j"; fi
  done
  JOBS=$keep
}

ask() { # $1 request id token, $2 spec id token, $3 spec type
  if [ "$3" != o ]; then
    text_result "$1" "acc-ui: error: spec must be a JSON object, not a string." ',"isError":true'
    return
  fi
  sid=${2#\"}; sid=${sid%\"}
  case $sid in
    '' | . | .. | *[!A-Za-z0-9._-]*) sid="" ;;
  esac
  if [ -z "$sid" ] || [ "${#sid}" -gt 64 ] || [ "$2" = "$sid" ]; then
    text_result "$1" "acc-ui: error: acc_ui_ask needs spec.id, 1-64 of A-Z a-z 0-9 . _ -, unique in this session." ',"isError":true'
    return
  fi
  d="$DIR/$sid"
  # Making the directory claims the id, so an id that waits or was answered
  # keeps its call and its answer.
  if ! { mkdir -p "$DIR" && mkdir "$d"; } 2>/dev/null; then
    if [ -d "$d" ]; then
      text_result "$1" "acc-ui: error: this spec.id was already used in this session; ask again with a new id." ',"isError":true'
    else
      text_result "$1" "acc-ui: error: can't create the answer directory." ',"isError":true'
    fi
    return
  fi
  printf '%s\n' "$1" >"$d/request"
  : >"$d/waiting"
  prune
  (
    TAG="w.$sid."
    waited=0
    while [ ! -f "$d/cancelled" ]; do
      if [ -s "$d/answer.json" ]; then
        answer=$(cat "$d/answer.json")
        case $answer in
          *"$NL"*) text_result "$1" "acc-ui: error: the answer file is malformed." ',"isError":true' ;;
          '{'*'}') reply "$1" "$answer" ;;
          *) text_result "$1" "acc-ui: error: the answer file is malformed." ',"isError":true' ;;
        esac
        break
      fi
      if [ "$waited" -ge "$TIMEOUT" ]; then
        text_result "$1" "acc-ui: timed out. The user hasn't answered yet. Carry on without it or end your turn; an answer given later arrives as a user message holding <acc-ui-submit id=...>{values}</acc-ui-submit>."
        break
      fi
      # A killed waiter's sleep lives on for up to a second: keep it off
      # the FIFO and the client's pipes.
      sleep 1 </dev/null >/dev/null 2>&1 3>&-
      waited=$((waited + 1))
    done
    rm -f "$d/waiting"
  ) &
  JOBS="$JOBS $!:$sid"
}

cancel() { # $1 request id token
  [ -n "$1" ] || return 0
  for j in $JOBS; do
    d="$DIR/${j#*:}"
    if [ -f "$d/waiting" ] && [ "$(cat "$d/request" 2>/dev/null)" = "$1" ]; then
      : >"$d/cancelled"
    fi
  done
}

stop() { # $1 "drain" to send the replies already made
  trap '' INT TERM HUP PIPE
  for j in $JOBS; do
    d="$DIR/${j#*:}"
    if [ -f "$d/waiting" ]; then
      kill "${j%%:*}" 2>/dev/null
      rm -f "$d/waiting"
    fi
  done
  if [ -n "$RUN" ]; then
    exec 3>&-
    [ "${1:-}" = drain ] || kill "$WRITER" 2>/dev/null
    wait "$WRITER" 2>/dev/null
    rm -rf "$RUN"
  fi
  exit 0
}

start_writer
trap stop INT TERM HUP PIPE

while IFS= read -r line || [ -n "$line" ]; do
  case $line in *[![:space:]]*) ;; *) continue ;; esac
  fields=$(printf '%s\n' "$line" | awk "$SCAN")
  if [ -z "$fields" ]; then
    fail null -32700 "Parse error"
    continue
  fi
  {
    IFS= read -r id
    IFS= read -r method
    IFS= read -r name
    IFS= read -r spec_id
    IFS= read -r pv
    IFS= read -r req
    IFS= read -r spec
  } <<ACC_UI_FIELDS
$fields
ACC_UI_FIELDS
  # The id goes back verbatim, so it must be a string, a number or null.
  case $id in
    '' | '"'*'"' | null) ;;
    [-0-9]*) case $id in *[!0-9eE.+-]*) id=bad ;; esac ;;
    *) id=bad ;;
  esac
  if [ "$id" = bad ]; then
    fail null -32600 "Invalid Request"
    continue
  fi
  case $method in
    '"notifications/cancelled"') cancel "$req"; continue ;;
    '"notifications/'*) continue ;;
  esac
  # Without an id it's a notification, which gets no reply.
  [ -n "$id" ] || continue
  case $method in
    '"initialize"')
      case $pv in '"'*'"') ;; *) pv='"2025-06-18"' ;; esac
      reply "$id" "{\"protocolVersion\":$pv,\"capabilities\":{\"tools\":{}},\"serverInfo\":{\"name\":\"acc_ui\",\"version\":\"0.1.0\"}}"
      ;;
    '"ping"') reply "$id" '{}' ;;
    '"tools/list"') reply "$id" "$TOOLS" ;;
    '"tools/call"')
      case $name in
        '"acc_ui_render"') text_result "$id" "acc-ui: shown. The user sees the component; don't repeat its content." ;;
        '"acc_ui_ask"') ask "$id" "$spec_id" "$spec" ;;
        *) fail "$id" -32602 "Unknown tool" ;;
      esac
      ;;
    *) fail "$id" -32601 "Method not found" ;;
  esac
done
stop drain
